import java.io.*;
import java.util.*;

public class C {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String inputLine = br.readLine();
        long val = Long.parseLong(inputLine);
        long res = compute(val);
        System.out.println(res);
    }

    static long[] ONES = new long[17];
    static {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    static long compute(long x) {
        return findMinCost(x, 16);
    }

    static long findMinCost(long x, int len) {
        x = Math.abs(x);
        if (x % ONES[len] == 0) {
            return (x / ONES[len]) * len;
        }
        long low = x / ONES[len];
        long high = low + 1;

        long cost1 = low * len + findMinCost(x - low * ONES[len], len - 1);
        long cost2 = high * len + findMinCost(high * ONES[len] - x, len - 1);
        return Math.min(cost1, cost2);
    }
}
